import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { engineResultBatchSchema } from "../src/index.js";

/**
 * Cross-language contract test. The fixture is regenerated by
 * services/scanner/tests/test_engine_result_batch_contract_fixture.py from a real
 * `EngineResultBatch` -- Python is the producer of this wire payload, so if
 * this schema ever rejects it, the two sides of the scanner/API boundary
 * have drifted.
 */
const fixturePath = fileURLToPath(
  new URL("../fixtures/engine-result-batch.json", import.meta.url),
);

describe("EngineResultBatch cross-language contract", () => {
  it("accepts the payload the Python scanner actually emits on /internal/v1/quotes/batch", () => {
    const payload: unknown = JSON.parse(readFileSync(fixturePath, "utf8"));
    const parsed = engineResultBatchSchema.parse(payload);
    expect(parsed.evaluations.length).toBeGreaterThan(0);
    expect(parsed.evaluations.some((value) => value.state === "READY")).toBe(
      true,
    );
    expect(parsed.timings.featureMs).toBeGreaterThan(0);
  });
});
